module bug_fixing_optimizer #(\n    parameter MAX_BUGS = 2,\n    parameter MAX_TIME = 8,\n    parameter STATE_SIZE = (MAX_TIME+2) ** MAX_BUGS,\n    parameter DATA_WIDTH = 64,\n    parameter FRACTION_WIDTH = 32\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] B,\n    input wire [3:0] T,\n    input wire [DATA_WIDTH-1:0] f,\n    input wire [DATA_WIDTH-1:0] p [0:MAX_BUGS-1],\n    input wire [DATA_WIDTH-1:0] s [0:MAX_BUGS-1],\n    output reg [DATA_WIDTH-1:0] expected_value,\n    output reg done\n);\n\n// State definitions\nlocalparam [3:0] S_IDLE        = 4'd0;\nlocalparam [3:0] S_PRECOMP     = 4'd1;\nlocalparam [3:0] S_INIT        = 4'd2;\nlocalparam [3:0] S_LOOP_T      = 4'd3;\nlocalparam [3:0] S_LOOP_STATE  = 4'd4;\nlocalparam [3:0] S_LOOP_BUG    = 4'd5;\nlocalparam [3:0] S_CALC        = 4'd6;\nlocalparam [3:0] S_UPDATE_BEST = 4'd7;\nlocalparam [3:0] S_STORE       = 4'd8;\nlocalparam [3:0] S_OUTPUT      = 4'd9;\nlocalparam [3:0] S_DONE        = 4'd10;\n\nreg [3:0] state, next_state;\n\n// DP memory arrays\nreg [DATA_WIDTH-1:0] dp [0:MAX_TIME][0:STATE_SIZE-1];\n\n// Precomputed powers\nreg [DATA_WIDTH-1:0] f_power [0:MAX_TIME];\n\n// Iteration variables\nreg [3:0] t;\nreg [6:0] state_idx;\nreg [1:0] bug_idx;\n\n// Temporary registers\nreg [DATA_WIDTH-1:0] p_current;\nreg [DATA_WIDTH-1:0] one_minus_p;\nreg [DATA_WIDTH-1:0] dp_success;\nreg [DATA_WIDTH-1:0] dp_failure;\nreg [DATA_WIDTH-1:0] term_success;\nreg [DATA_WIDTH-1:0] term_failure;\nreg [DATA_WIDTH-1:0] value;\nreg [DATA_WIDTH-1:0] best;\n\n// State decoding signals\nwire [3:0] bug0_state = state_idx % (T+4'd2);\nwire [3:0] bug1_state = state_idx / (T+4'd2);\nwire bug0_fixed = (bug0_state == T+4'd1);\nwire bug1_fixed = (bug1_state == T+4'd1);\n\nwire [3:0] bug0_state_success = T+4'd1;\nwire [3:0] bug0_state_failure = (bug0_state < T) ? bug0_state + 4'd1 : T;\nwire [3:0] bug1_state_success = T+4'd1;\nwire [3:0] bug1_state_failure = (bug1_state < T) ? bug1_state + 4'd1 : T;\n\nwire [6:0] state_success_bug0 = bug0_state_success * (T+4'd2) + bug1_state;\nwire [6:0] state_failure_bug0 = bug0_state_failure * (T+4'd2) + bug1_state;\nwire [6:0] state_success_bug1 = bug0_state * (T+4'd2) + bug1_state_success;\nwire [6:0] state_failure_bug1 = bug0_state * (T+4'd2) + bug1_state_failure;\n\ninteger i, j;  // Loop indices\n\n// Fixed-point arithmetic functions\nfunction [DATA_WIDTH-1:0] fp_mult;\n    input [DATA_WIDTH-1:0] a;\n    input [DATA_WIDTH-1:0] b;\n    reg [127:0] prod;\n    begin\n        prod = a * b;\n        fp_mult = prod[95:32];\n    end\nendfunction\n\nfunction [DATA_WIDTH-1:0] fp_add;\n    input [DATA_WIDTH-1:0] a;\n    input [DATA_WIDTH-1:0] b;\n    begin\n        fp_add = a + b;\n    end\nendfunction\n\nfunction [DATA_WIDTH-1:0] fp_sub;\n    input [DATA_WIDTH-1:0] a;\n    input [DATA_WIDTH-1:0] b;\n    begin\n        fp_sub = a - b;\n    end\nendfunction\n\n// Main state machine\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= S_IDLE;\n        done <= 1'b0;\n        expected_value <= {DATA_WIDTH{1'b0}};\n        t <= 4'd0;\n        state_idx <= 7'd0;\n        bug_idx <= 2'd0;\n        // Initialize all dp entries\n        for (i = 0; i <= MAX_TIME; i = i + 1) begin\n            for (j = 0; j < STATE_SIZE; j = j + 1) begin\n                dp[i][j] <= {DATA_WIDTH{1'b0}};\n            end\n        end\n        // Initialize f_power array\n        for (i = 0; i <= MAX_TIME; i = i + 1) begin\n            f_power[i] <= {DATA_WIDTH{1'b0}};\n        end\n    end else begin\n        case (state)\n            S_IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    state <= S_PRECOMP;\n                end\n            end\n\n            S_PRECOMP: begin\n                f_power[0] <= {32'd1, 32'd0};  // 1.0 in Q16.16\n                for (i = 1; i <= MAX_TIME; i = i + 1) begin\n                    f_power[i] <= fp_mult(f_power[i-1], f);\n                end\n                state <= S_INIT;\n            end\n\n            S_INIT: begin\n                // Initialize dp[T][*] = 0\n                for (j = 0; j < STATE_SIZE; j = j + 1) begin\n                    dp[MAX_TIME][j] <= {DATA_WIDTH{1'b0}};\n                end\n                t <= MAX_TIME - 4'd1;\n                state_idx <= 7'd0;\n                state <= S_LOOP_T;\n            end\n\n            S_LOOP_T: begin\n                if (t == 4'd15) begin  // Underflow check\n                    state <= S_OUTPUT;\n                end else begin\n                    state <= S_LOOP_STATE;\n                end\n            end\n\n            S_LOOP_STATE: begin\n                if (state_idx >= STATE_SIZE) begin\n                    t <= t - 4'd1;\n                    state_idx <= 7'd0;\n                    state <= S_LOOP_T;\n                end else begin\n                    bug_idx <= 2'd0;\n                    best <= {DATA_WIDTH{1'b0}};\n                    state <= S_LOOP_BUG;\n                end\n            end\n\n            S_LOOP_BUG: begin\n                if (bug_idx >= MAX_BUGS) begin\n                    dp[t][state_idx] <= best;\n                    state_idx <= state_idx + 7'd1;\n                    state <= S_LOOP_STATE;\n                end else if ((bug_idx == 2'd0 && bug0_fixed) || (bug_idx == 2'd1 && bug1_fixed)) begin\n                    bug_idx <= bug_idx + 2'd1;\n                end else begin\n                    state <= S_CALC;\n                end\n            end\n\n            S_CALC: begin\n                // Calculation happens in comb block\n                state <= S_UPDATE_BEST;\n            end\n\n            S_UPDATE_BEST: begin\n                if (value > best) begin\n                    best <= value;\n                end\n                bug_idx <= bug_idx + 2'd1;\n                state <= S_LOOP_BUG;\n            end\n\n            S_OUTPUT: begin\n                expected_value <= dp[4'd0][7'd0];\n                done <= 1'b1;\n                state <= S_DONE;\n            end\n\n            S_DONE: begin\n                done <= 1'b0;\n                state <= S_IDLE;\n            end\n\n            default: state <= S_IDLE;\n        endcase\n    end\nend\n\n// State calculation combinational logic\nalways @(*) begin\n    // Defaults\n    p_current = {DATA_WIDTH{1'b0}};\n    one_minus_p = {DATA_WIDTH{1'b0}};\n    dp_success = {DATA_WIDTH{1'b0}};\n    dp_failure = {DATA_WIDTH{1'b0}};\n    term_success = {DATA_WIDTH{1'b0}};\n    term_failure = {DATA_WIDTH{1'b0}};\n    value = {DATA_WIDTH{1'b0}};\n\n    if (state == S_CALC) begin\n        if (bug_idx == 2'd0 && !bug0_fixed) begin\n            p_current = fp_mult(p[0], f_power[bug0_state]);\n            one_minus_p = fp_sub({32'd1, 32'd0}, p_current);  // 1.0 in Q16.16\n            dp_success = dp[t+4'd1][state_success_bug0];\n            dp_failure = dp[t+4'd1][state_failure_bug0];\n        end else if (bug_idx == 2'd1 && !bug1_fixed) begin\n            p_current = fp_mult(p[1], f_power[bug1_state]);\n            one_minus_p = fp_sub({32'd1, 32'd0}, p_current);  // 1.0 in Q16.16\n            dp_success = dp[t+4'd1][state_success_bug1];\n            dp_failure = dp[t+4'd1][state_failure_bug1];\n        end\n        \n        term_success = fp_mult(p_current, fp_add(s[bug_idx], dp_success));\n        term_failure = fp_mult(one_minus_p, dp_failure);\n        value = fp_add(term_success, term_failure);\n    end\nend\n\nendmodule